      titles: ['Operation {G}', 'The {G} Protocol', 'Our Agent in {S}', 'Codename: {G}'],
      coda: ["The file was stamped TOP SECRET and locked away forever. Somebody stamped it upside down. Nobody noticed.", "AGENT ZERO: Mission accomplished, agent. This conversation never happened. ...Lovely to see you, though."],
